              <Link href={`/workouts/${workout.id}`} className="text-xl font-semibold underline">
                {workout.title}
              </Link>
              <p className="text-sm text-zinc-500">{formatDay(workout.day)}</p>
            </li>
          ))}
        </ul>
      )}
    </main>
  );
}

